import java.lang.reflect.*;
public class DumpNativeStars {public static void main(String[]args)throws Exception{Field u=sun.misc.Unsafe.class.getDeclaredField("theUnsafe");u.setAccessible(true);sun.misc.Unsafe unsafe=(sun.misc.Unsafe)u.get(null);Class<?> c=Class.forName("m");Object object=unsafe.allocateInstance(c);Method f=c.getDeclaredMethod("f");f.setAccessible(true);f.invoke(object);System.out.println("quads="+na.vertices.size()/4);for(int i=0;i<Math.min(8,na.vertices.size());i++){double[]p=na.vertices.get(i);System.out.printf(java.util.Locale.ROOT,"%.15f %.15f %.15f%n",p[0],p[1],p[2]);}}}
